from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
Left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
Right__attachment = Motor(Port.E, Direction.CLOCKWISE)
Left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
Right_drive = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_drive, Right_drive, 56, 114)


# The main program starts here.
drive_base.straight(400)
print('a')
wait(3)
Right__attachment.run_angle(500, -360)
print('b')
wait(1)
drive_base.straight(-41)
print('c')
wait(1)
Right__attachment.run_angle(1, 210)
print('d')
wait(1)
Right__attachment.run_angle(500, -300)
wait(1)
Right__attachment.run_angle(500, 20)
wait(1)
Right__attachment.run_angle(500, -40)
wait(1)
Right__attachment.run_angle(500, 20)
wait(1)
Right__attachment.run_angle(500, -40)
